#!/usr/bin/env python3"""Reliable download utility for Cozy TTS models using aria2c.This module provides robust model downloading using aria2c for:- HuggingFace models (via CDN URLs)- Direct file downloads- ModelScope models (via direct URLs)Key learnings from previous implementation:- HuggingFace Hub gets throttled and connections close- aria2c has built-in retry, resume, and parallel connection support- Models should be skipped if already downloaded- Validation should happen after download"""import argparseimport hashlibimport loggingimport shutilimport subprocessimport sysimport timefrom collections.abc import Callablefrom pathlib import Pathfrom typing import Literalfrom src.constants import PROJECT_ROOT, ROOT_MODELS_DIR, HUGGINGFACE_BASE_URLlogger = logging.getLogger(__name__)logging.basicConfig(    level=logging.INFO,    format='%(asctime)s - %(name)s - %(levelname)s - %(message)s')# =============================================================================# Model Configuration - Centralized download URLs and file lists# =============================================================================MODEL_CONFIGS = {    "kokoro": {        "type": "huggingface",        "repo_id": "hexgrad/Kokoro-82M",        "output_dir": "models/kokoro",        "files": [            "kokoro-v1.0.onnx",            "voices-v1.0.bin",            "config.json",        ],        "description": "Kokoro ONNX TTS model (82MB)",    },    "vibevoice": {        "type": "huggingface",        "repo_id": "vibevoice/VibeVoice-1.5B",        "output_dir": "models/vibevoice-1.5b",        "files": "all",  # Download all safetensors and config files        "description": "VibeVoice 1.5B conversational TTS",        "patterns": ["*.safetensors*", "*.json", "*.txt"],    },    "vibevoice-7b": {        "type": "huggingface",        "repo_id": "vibevoice/VibeVoice-7B",        "output_dir": "models/vibevoice-7b",        "files": "all",        "description": "VibeVoice 7B conversational TTS (larger)",        "patterns": ["*.safetensors*", "*.json"],    },    "indextts": {        "type": "github-lfs",  # Uses git LFS from GitHub        "repo_url": "https://github.com/index-tts/index-tts.git",        "output_dir": "src/extensions/external/index_tts/index-tts/checkpoints",  # Git repo's checkpoints dir        "description": "IndexTTS-2 emotional TTS (via git LFS)",        "alternative_hf": "IndexTeam/IndexTTS-2",  # HuggingFace alternative    },    "gptsovits": {        "type": "huggingface",        "repo_id": "lj1995/GPT-SoVITS",        "output_dir": "models/gpt_sovits",        "files": [            "s1bert25hz-2kh-longer-epoch=68e-step=50232.ckpt",            "s2G488k.pth",        ],        "description": "GPT-SoVITS voice cloning TTS",        "patterns": ["*.ckpt", "*.pth"],    },    "gptsovits-pretrained": {        "type": "huggingface",        "repo_id": "hfl/chinese-roberta-wwm-ext-large",        "output_dir": "models/gptsovits_pretrained",        "files": "all",        "description": "GPT-SoVITS pretrained BERT model (chinese-roberta-wwm-ext-large) - auto-downloaded if missing",        "patterns": ["*.json", "*.txt", "*.bin", "*.model"],    },    "gptsovits-cnhubert": {        "type": "huggingface",        "repo_id": "TencentGameMate/chinese-hubert-base",        "output_dir": "models/gptsovits_cnhubert",        "files": "all",        "description": "GPT-SoVITS pretrained CNHubert model (chinese-hubert-base) - auto-downloaded if missing",        "patterns": ["*.json", "*.txt", "*.bin", "*.pt", "*.th", "*.safetensors*"],    },    "maya1": {        "type": "huggingface",        "repo_id": "maya-research/maya1",        "output_dir": "models/maya1",        "files": "all",        "description": "Maya1 emotional TTS",        "patterns": ["*.safetensors*", "*.json", "*.bin", "*.txt", "*.model"],    },    "qwen-omni": {        "type": "huggingface",        "repo_id": "cyankiwi/Qwen3-Omni-30B-A3B-Instruct-AWQ-4bit",        "output_dir": "models/qwen-omni",        "files": "all",        "description": "Qwen3-Omni-30B AWQ 4-bit for Audio QA (~30GB)",        "patterns": ["*.safetensors*", "*.json", "*.txt", "*.py", "model/*"],    },    "qwen-omni-gguf": {        "type": "huggingface",        "repo_id": "Mungert/Qwen2.5-Omni-3B-GGUF",        "output_dir": "models/qwen-omni-gguf",        "files": "all",        "description": "Qwen2.5-Omni-3B GGUF for Audio QA with llama.cpp (~6GB)",        "patterns": ["*.gguf"],    },    "qwen2.5-omni-7b": {        "type": "huggingface",        "repo_id": "Qwen/Qwen2.5-Omni-7B",        "output_dir": "models/qwen2.5-omni-7b",        "files": "all",        "description": "Qwen2.5-Omni-7B for Audio QA (~14GB) - smaller & faster",        "patterns": ["*.safetensors*", "*.json", "*.txt"],    },}# =============================================================================# Model Integrity and Validation# =============================================================================def compute_file_checksum(file_path: Path, algorithm: Literal["md5", "sha256"] = "md5") -> str:    """    Compute checksum of a file.    Args:        file_path: Path to the file        algorithm: Hash algorithm to use (md5 or sha256)    Returns:        Hexadecimal checksum string    """    hash_func = hashlib.md5() if algorithm == "md5" else hashlib.sha256()    with open(file_path, "rb") as f:        # Read in chunks to handle large files        for chunk in iter(lambda: f.read(8192), b""):            hash_func.update(chunk)    return hash_func.hexdigest()def validate_downloaded_file(    file_path: Path,    expected_checksum: str | None = None,    min_size: int = 1000,) -> tuple[bool, str]:    """    Validate a downloaded file.    Args:        file_path: Path to the downloaded file        expected_checksum: Expected checksum (optional, if None, only checks size)        min_size: Minimum file size in bytes (default: 1000)    Returns:        Tuple of (is_valid, error_message)    """    if not file_path.exists():        return False, "File does not exist"    file_size = file_path.stat().st_size    # Check minimum size    if file_size < min_size:        return False, f"File too small: {file_size} bytes (minimum: {min_size})"    # Check for incomplete download markers    incomplete_markers = [        file_path.with_suffix(file_path.suffix + ".incomplete"),        file_path.with_suffix(file_path.suffix + ".aria2"),        file_path.parent / f".{file_path.name}.tmp",    ]    for marker in incomplete_markers:        if marker.exists():            return False, f"Incomplete download (marker file exists: {marker.name})"    # Check for zero-byte files    if file_size == 0:        return False, "File is empty (0 bytes)"    # Verify checksum if provided    if expected_checksum:        actual_checksum = compute_file_checksum(file_path)        if actual_checksum.lower() != expected_checksum.lower():            return False, f"Checksum mismatch: expected {expected_checksum}, got {actual_checksum}"    return True, "Valid"def find_incomplete_downloads(model_dir: Path | None = None) -> list[Path]:    """    Scan for incomplete or failed downloads in model directories.    Args:        model_dir: Root models directory (defaults to project_root/models)    Returns:        List of incomplete file paths found    """    if model_dir is None:        # Find project root by looking for marker files        file_path = Path(__file__).resolve()        current = file_path        while current != current.parent:            if (current / "pyproject.toml").exists() or (current / "backend" / "pyproject.toml").exists():                break            current = current.parent        # Determine the actual models directory        # The models/ directory might be at the detected level or one level up        # Prefer project root level models over backend/models        if (current.parent / "models").exists() and current.name == "backend":            # We're in backend/ and models/ is one level up (most common case)            model_dir = current.parent / "models"        elif current.name == "backend":            # We're in backend/ but parent doesn't have models, check backend/models            model_dir = current / "models"        elif (current / "models").exists():            # models/ exists at this level            model_dir = current / "models"        elif (current / "backend" / "models").exists():            # backend/models/ exists            model_dir = current / "backend" / "models"        else:            # Fallback            model_dir = current / "models"    incomplete_files = []    # Common incomplete download patterns    patterns = [        "*.incomplete",      # HuggingFace incomplete downloads        "*.aria2",           # aria2c partial downloads        ".*.tmp",            # Generic temp files (hidden)        "*.download",        # Generic download temp files        "*.part",            # Partial downloads    ]    for pattern in patterns:        for file_path in model_dir.rglob(pattern):            incomplete_files.append(file_path)    # Also check for hidden files with random hex names (like the .Qwen... file we found)    for file_path in model_dir.rglob(".*"):        # Skip .git and other normal hidden files        if any(skip in str(file_path) for skip in [".git", ".venv", "__pycache__", ".github"]):            continue        # Check for suspicious patterns (long hex strings in name)        if file_path.is_file():            name = file_path.name            # Pattern 1: Files with multiple extensions and random-looking suffixes            # Example: .Qwen2.5-Omni-3B-bf16.gguf.zhEIzv.7L5HXb            # These are typically atomic rename temp files            if name.startswith("."):                # Count dots in the filename (excluding leading dot)                dot_count = name.count(".") - 1  # Subtract 1 for the leading dot                # If file has multiple extensions (lots of dots), it's suspicious                if dot_count >= 2:                    # Check if the last parts look like random hex/base64 strings                    parts = name.split(".")[1:]  # Skip the leading empty part                    for part in parts[-2:]:  # Check the last 2 parts                        # Random strings are typically long and contain mixed case alphanumerics                        if len(part) > 5 and part.isalnum() and any(c.isupper() for c in part):                            incomplete_files.append(file_path)                            break    return incomplete_filesdef cleanup_incomplete_downloads(model_dir: Path | None = None, dry_run: bool = False) -> dict[str, list[Path]]:    """    Clean up incomplete or failed downloads.    Args:        model_dir: Root models directory        dry_run: If True, only report what would be deleted without actually deleting    Returns:        Dictionary with 'deleted' and 'would_delete' lists    """    incomplete = find_incomplete_downloads(model_dir)    # Use same path detection for cleanup info display    if model_dir is None:        file_path = Path(__file__).resolve()        current = file_path        while current != current.parent:            if (current / "pyproject.toml").exists() or (current / "backend" / "pyproject.toml").exists():                break            current = current.parent        if (current / "backend" / "pyproject.toml").exists():            project_root = current        elif (current / "pyproject.toml").exists():            project_root = current.parent        else:            project_root = file_path.parent.parent.parent.parent.parent    else:        project_root = model_dir.parent.parent  # Go up from models/ to project root    result = {        "deleted": [] if not dry_run else incomplete,        "would_delete": incomplete if dry_run else [],        "space_freed": 0,    }    for file_path in incomplete:        file_size = file_path.stat().st_size if file_path.exists() else 0        if dry_run:            logger.info(f"Would delete: {file_path} ({file_size:,} bytes)")            result["space_freed"] += file_size        else:            try:                file_path.unlink()                logger.info(f"Deleted incomplete download: {file_path} ({file_size:,} bytes)")                result["deleted"].append(file_path)                result["space_freed"] += file_size            except Exception as e:                logger.error(f"Failed to delete {file_path}: {e}")    return resultdef validate_model_files(model_name: str, project_root: Path | None = None) -> dict[str, list[Path]]:    """    Validate all files for a specific model.    Args:        model_name: Name of the model to validate        project_root: Project root directory    Returns:        Dictionary with 'valid', 'invalid', and 'missing' file lists    """    if project_root is None:        project_root = PROJECT_ROOT    if model_name not in MODEL_CONFIGS:        logger.error(f"Unknown model: {model_name}")        return {"valid": [], "invalid": [], "missing": []}    config = MODEL_CONFIGS[model_name]    model_path = project_root / config["output_dir"]    result = {"valid": [], "invalid": [], "missing": []}    if not model_path.exists():        # All files are missing        return result    # Check for common model file types    patterns = ["*.safetensors*", "*.gguf", "*.bin", "*.pth", "*.pt", "*.ckpt", "*.onnx"]    for pattern in patterns:        for file_path in model_path.rglob(pattern):            is_valid, msg = validate_downloaded_file(file_path)            if is_valid:                result["valid"].append(file_path)            else:                result["invalid"].append(file_path)    return result# =============================================================================# aria2c Download Functions# =============================================================================def check_aria2c() -> bool:    """Check if aria2c is available on the system."""    try:        result = subprocess.run(            ["aria2c", "--version"],            capture_output=True,            text=True,            timeout=5        )        return result.returncode == 0    except (FileNotFoundError, subprocess.TimeoutExpired):        return Falsedef install_aria2c() -> bool:    """Attempt to install aria2c if not available."""    if check_aria2c():        return True    logger.info("aria2c not found, attempting to install...")    # Try different installation methods based on platform    install_commands = [        ["sudo", "apt-get", "install", "-y", "aria2"],        ["brew", "install", "aria2"],        ["sudo", "dnf", "install", "-y", "aria2"],        ["sudo", "yum", "install", "-y", "aria2"],    ]    for cmd in install_commands:        try:            result = subprocess.run(cmd, capture_output=True, text=True, timeout=300)            if result.returncode == 0 and check_aria2c():                logger.info("aria2c installed successfully")                return True        except (subprocess.TimeoutExpired, FileNotFoundError):            continue    logger.error("Failed to install aria2c")    return Falsedef ensure_aria2c() -> bool:    """Ensure aria2c is available, installing if necessary."""    if not check_aria2c():        logger.warning("aria2c not found. Attempting to install...")        return install_aria2c()    return Truedef download_file_with_aria2c(    url: str,    output_path: Path,    max_retries: int = 10,    timeout: int = 600,  # Max allowed by aria2c is 600    connections: int = 16,) -> Path:    """    Download a single file using aria2c with robust retry logic.    Args:        url: URL to download        output_path: Full path to save the file (including filename)        max_retries: Maximum number of retry attempts        timeout: Timeout per download attempt in seconds        connections: Number of parallel connections    Returns:        Path to the downloaded file    Raises:        RuntimeError: If download fails after all retries    """    output_path = Path(output_path)    output_path.parent.mkdir(parents=True, exist_ok=True)    # Build aria2c command with optimal settings    cmd = [        "aria2c",        f"--dir={output_path.parent}",        f"--out={output_path.name}",        f"--max-tries={max_retries}",        "--retry-wait=5",        f"--timeout={timeout}",        f"--split={connections}",        "--min-split-size=1M",        "--continue=true",        "--check-certificate=true",        "--auto-file-renaming=true",        f"--max-file-not-found={max_retries}",        "--summary-interval=60",    ]    # Add user agent    cmd.append("--user-agent=Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36")    cmd.append(url)    # Attempt download with retries    last_error = None    for attempt in range(max_retries):        try:            logger.info(f"Download attempt {attempt + 1}/{max_retries}: {url}")            result = subprocess.run(                cmd,                capture_output=True,                text=True,                timeout=timeout + 60,                cwd=str(output_path.parent)            )            if result.returncode == 0:                if output_path.exists() and output_path.stat().st_size > 0:                    # Validate the downloaded file                    is_valid, msg = validate_downloaded_file(output_path)                    if not is_valid:                        last_error = f"Download validation failed: {msg}"                        logger.warning(f"File validation failed: {msg}")                        # Clean up invalid file                        try:                            output_path.unlink()                        except Exception:                            pass                    else:                        logger.info(f"Successfully downloaded and validated: {output_path} ({output_path.stat().st_size} bytes)")                        return output_path                else:                    last_error = f"Download completed but file not found: {output_path}"            else:                last_error = f"aria2c returned code {result.returncode}: {result.stderr}"            # Clean up partial download if it failed            if output_path.exists() and output_path.stat().st_size == 0:                output_path.unlink()                aria2c_files = list(output_path.parent.glob("*.aria2"))                for f in aria2c_files:                    f.unlink()        except subprocess.TimeoutExpired:            last_error = f"Download timed out after {timeout} seconds"        except Exception as e:            last_error = f"Download error: {e}"        if attempt < max_retries - 1:            wait_time = (attempt + 1) * 5            logger.warning(f"Download failed, retrying in {wait_time}s: {last_error}")            time.sleep(wait_time)    raise RuntimeError(f"Failed to download after {max_retries} attempts: {last_error}")def build_huggingface_url(repo_id: str, filename: str, revision: str = "main") -> str:    """Build a direct HuggingFace CDN URL for a file."""    from src.constants import HUGGINGFACE_BASE_URL    return f"{HUGGINGFACE_BASE_URL}/{repo_id}/resolve/{revision}/{filename}"# =============================================================================# Model-specific Download Functions# =============================================================================def is_model_downloaded(model_name: str, project_root: Path | None = None) -> bool:    """    Check if a model is already downloaded.    Args:        model_name: Name of the model to check        project_root: Project root directory (optional, will auto-detect)    Returns:        True if model exists and has ALL required files, False otherwise    """    if project_root is None:        project_root = PROJECT_ROOT    if model_name not in MODEL_CONFIGS:        return False    config = MODEL_CONFIGS[model_name]    model_path = project_root / config["output_dir"]    if not model_path.exists():        return False    # Special check for qwen-omni - verify all safetensors files exist    if model_name == "qwen-omni":        index_file = model_path / "model.safetensors.index.json"        if index_file.exists():            try:                import json                with open(index_file) as f:                    index = json.load(f)                # Get unique filenames from weight map                weight_map = index.get("weight_map", {})                needed_files = set(weight_map.values())                # Check if all files exist and have content                for filename in needed_files:                    file_path = model_path / filename                    if not file_path.exists() or file_path.stat().st_size < 1000:                        return False                return True            except Exception:                pass    # Default check: directory has safetensors files    safetensors_files = list(model_path.glob("*.safetensors"))    if not safetensors_files:        return False    # Check that at least one safetensors file has substantial content    for f in safetensors_files:        if f.stat().st_size > 1_000_000:  # At least 1MB            return True    return Falsedef download_huggingface_model(    repo_id: str,    output_dir: Path,    files: list[str] | str = "all",    patterns: list[str] | None = None,    max_retries: int = 10,) -> bool:    """    Download a HuggingFace model using aria2c.    Args:        repo_id: HuggingFace repository ID (e.g., "hexgrad/Kokoro-82M")        output_dir: Directory to save the model        files: List of specific files to download, or "all" for pattern-based        patterns: File patterns if files="all"        max_retries: Maximum retry attempts    Returns:        True if successful    """    output_dir = Path(output_dir)    output_dir.mkdir(parents=True, exist_ok=True)    # Ensure aria2c is available    if not ensure_aria2c():        raise RuntimeError("aria2c is required but not available")    if files == "all":        # For "all" files, we need to use HuggingFace to list them        # This is the only place we use HF Hub, just for listing        try:            from huggingface_hub import list_repo_files            repo_files = list_repo_files(repo_id, repo_type="model")            if patterns:                # Filter by patterns                import fnmatch                filtered = []                for f in repo_files:                    for pattern in patterns:                        if fnmatch.fnmatch(f, pattern):                            filtered.append(f)                            break                files_to_download = filtered            else:                files_to_download = repo_files        except ImportError:            # Fallback: download known critical files            logger.warning("huggingface_hub not available, downloading critical files only")            files_to_download = ["config.json", "model.safetensors.index.json"]        except Exception as e:            logger.warning(f"Failed to list repository files: {e}")            return False    else:        files_to_download = files    logger.info(f"Downloading {len(files_to_download)} files from {repo_id}")    success_count = 0    failed_files = []    for filename in files_to_download:        # Skip directories        if filename.endswith('/'):            continue        url = build_huggingface_url(repo_id, filename)        output_path = output_dir / filename        # Skip if already exists and has content        if output_path.exists() and output_path.stat().st_size > 1000:            logger.info(f"Skipping existing file: {filename}")            success_count += 1            continue        try:            download_file_with_aria2c(url, output_path, max_retries=max_retries)            success_count += 1        except Exception as e:            logger.error(f"Failed to download {filename}: {e}")            failed_files.append(filename)    logger.info(f"Downloaded {success_count}/{len(files_to_download)} files successfully")    if failed_files:        logger.warning(f"Failed files: {failed_files[:5]}{'...' if len(failed_files) > 5 else ''}")    return success_count > 0def _download_kokoro_internal(output_dir: Path, max_retries: int = 10) -> bool:    """Download Kokoro model."""    config = MODEL_CONFIGS["kokoro"]    logger.info(f"Downloading {config['description']}...")    return download_huggingface_model(        repo_id=config["repo_id"],        output_dir=output_dir,        files=config["files"],        max_retries=max_retries,    )def _download_vibevoice_1_5b_internal(output_dir: Path, max_retries: int = 10) -> bool:    """Download VibeVoice 1.5B model."""    config = MODEL_CONFIGS["vibevoice"]    logger.info(f"Downloading {config['description']}...")    return download_huggingface_model(        repo_id=config["repo_id"],        output_dir=output_dir,        files=config["files"],        patterns=config.get("patterns"),        max_retries=max_retries,    )def _download_vibevoice_7b_internal(output_dir: Path, max_retries: int = 10) -> bool:    """Download VibeVoice 7B model."""    config = MODEL_CONFIGS["vibevoice-7b"]    logger.info(f"Downloading {config['description']}...")    return download_huggingface_model(        repo_id=config["repo_id"],        output_dir=output_dir,        files=config["files"],        patterns=config.get("patterns"),        max_retries=max_retries,    )def _download_maya1_internal(output_dir: Path, max_retries: int = 10) -> bool:    """Download Maya1 model."""    config = MODEL_CONFIGS["maya1"]    logger.info(f"Downloading {config['description']}...")    return download_huggingface_model(        repo_id=config["repo_id"],        output_dir=output_dir,        files=config["files"],        patterns=config.get("patterns"),        max_retries=max_retries,    )def _download_gptsovits_internal(output_dir: Path, max_retries: int = 10) -> bool:    """Download GPT-SoVITS models."""    config = MODEL_CONFIGS["gptsovits"]    logger.info(f"Downloading {config['description']}...")    return download_huggingface_model(        repo_id=config["repo_id"],        output_dir=output_dir,        files=config["files"],        patterns=config.get("patterns"),        max_retries=max_retries,    )def _download_gptsovits_pretrained_internal(output_dir: Path, max_retries: int = 10) -> bool:    """Download GPT-SoVITS pretrained BERT model."""    config = MODEL_CONFIGS["gptsovits-pretrained"]    logger.info(f"Downloading {config['description']}...")    return download_huggingface_model(        repo_id=config["repo_id"],        output_dir=output_dir,        files=config["files"],        patterns=config.get("patterns"),        max_retries=max_retries,    )def _download_gptsovits_cnhubert_internal(output_dir: Path, max_retries: int = 10) -> bool:    """Download GPT-SoVITS pretrained CNHubert model."""    config = MODEL_CONFIGS["gptsovits-cnhubert"]    logger.info(f"Downloading {config['description']}...")    return download_huggingface_model(        repo_id=config["repo_id"],        output_dir=output_dir,        files=config["files"],        patterns=config.get("patterns"),        max_retries=max_retries,    )def _download_qwen_omni_internal(output_dir: Path, max_retries: int = 10) -> bool:    """Download Qwen-Omni model for Audio QA."""    config = MODEL_CONFIGS["qwen-omni"]    logger.info(f"Downloading {config['description']}...")    output_dir = Path(output_dir)    output_dir.mkdir(parents=True, exist_ok=True)    # Use huggingface-cli download to get all files    try:        import subprocess        cmd = [            "huggingface-cli",            "download",            config["repo_id"],            "--local-dir", str(output_dir),            "--local-dir-use-symlinks", "False",        ]        logger.info("Running huggingface-cli download (all files)...")        result = subprocess.run(cmd, capture_output=True, text=True, timeout=21600)  # 6 hours        if result.returncode == 0:            # Verify safetensors files exist            safetensors_files = list(output_dir.rglob("*.safetensors"))            if not safetensors_files:                logger.warning("Download completed but no safetensors files found!")                logger.info("The model may use a different format (e.g., .bin files)")            else:                logger.info(f"Found {len(safetensors_files)} safetensors file(s)")            return True        else:            logger.error(f"Download failed: {result.stderr}")            if result.stdout:                logger.error(f"stdout: {result.stdout}")            return False    except FileNotFoundError:        logger.error("huggingface-cli not found. Install with: pip install huggingface-hub")        return False    except subprocess.TimeoutExpired:        logger.error("Download timed out after 6 hours")        return False    except Exception as e:        logger.error(f"Download error: {e}")        return Falsedef _download_qwen_omni_gguf_internal(output_dir: Path, max_retries: int = 10) -> bool:    """Download Qwen-Omni GGUF model for Audio QA with llama.cpp."""    config = MODEL_CONFIGS["qwen-omni-gguf"]    logger.info(f"Downloading {config['description']}...")    # Explicitly download the GGUF files without relying on huggingface_hub    gguf_files = [        "Qwen2.5-Omni-3B-bf16.gguf",        "Qwen2.5-Omni-3B-bf16_q8_0.gguf",        "config.json",        "generation_config.json",        "tokenizer.json",        "tokenizer_config.json",    ]    output_dir = Path(output_dir)    output_dir.mkdir(parents=True, exist_ok=True)    # Ensure aria2c is available    if not ensure_aria2c():        raise RuntimeError("aria2c is required but not available")    success_count = 0    failed_files = []    for filename in gguf_files:        url = build_huggingface_url(config["repo_id"], filename)        output_path = output_dir / filename        # Skip if already exists and has content        if output_path.exists() and output_path.stat().st_size > 1000:            logger.info(f"Skipping existing file: {filename}")            success_count += 1            continue        try:            download_file_with_aria2c(url, output_path, max_retries=max_retries)            success_count += 1        except Exception as e:            logger.error(f"Failed to download {filename}: {e}")            failed_files.append(filename)    logger.info(f"Downloaded {success_count}/{len(gguf_files)} files successfully")    if failed_files:        logger.warning(f"Failed files: {failed_files[:5]}{'...' if len(failed_files) > 5 else ''}")    return success_count > 0def _download_indextts_internal(output_dir: Path, max_retries: int = 10) -> bool:    """    Download IndexTTS model.    IndexTTS uses git LFS. Try git LFS first, fallback to HuggingFace.    """    config = MODEL_CONFIGS["indextts"]    logger.info(f"Downloading {config['description']}...")    # Try HuggingFace alternative first (more reliable than git LFS)    logger.info("Using HuggingFace mirror for IndexTTS-2...")    return download_huggingface_model(        repo_id=config["alternative_hf"],        output_dir=output_dir,        files="all",        patterns=["*.yaml", "*.json", "*.pt", "*.pth", "*.ckpt", "*.bin", "*.safetensors*"],        max_retries=max_retries,    )def download_model_by_name(    model_name: str,    project_root: Path | None = None,    max_retries: int = 10,) -> bool:    """    Download a model by name.    Args:        model_name: Name of the model to download        project_root: Project root directory        max_retries: Maximum retry attempts    Returns:        True if successful    """    if project_root is None:        project_root = PROJECT_ROOT    if model_name not in MODEL_CONFIGS:        logger.error(f"Unknown model: {model_name}")        return False    # Check if already downloaded    if is_model_downloaded(model_name, project_root):        logger.info(f"Model '{model_name}' already downloaded, skipping")        return True    config = MODEL_CONFIGS[model_name]    output_dir = project_root / config["output_dir"]    logger.info(f"Downloading model '{model_name}': {config['description']}")    print(f"\n{'='*60}")    print(f"Downloading: {config['description']}")    print(f"Output: {output_dir}")    print(f"{'='*60}\n")    try:        # Route to specific download function        if model_name == "kokoro":            result = _download_kokoro_internal(output_dir, max_retries)        elif model_name == "vibevoice":            result = _download_vibevoice_1_5b_internal(output_dir, max_retries)        elif model_name == "vibevoice-7b":            result = _download_vibevoice_7b_internal(output_dir, max_retries)        elif model_name == "maya1":            result = _download_maya1_internal(output_dir, max_retries)        elif model_name == "gptsovits":            result = _download_gptsovits_internal(output_dir, max_retries)        elif model_name == "gptsovits-pretrained":            result = _download_gptsovits_pretrained_internal(output_dir, max_retries)        elif model_name == "gptsovits-cnhubert":            result = _download_gptsovits_cnhubert_internal(output_dir, max_retries)        elif model_name == "indextts":            result = _download_indextts_internal(output_dir, max_retries)        elif model_name == "qwen-omni":            result = _download_qwen_omni_internal(output_dir, max_retries)        elif model_name == "qwen-omni-gguf":            result = _download_qwen_omni_gguf_internal(output_dir, max_retries)        elif model_name == "qwen2.5-omni-7b":            result = download_huggingface_model(                repo_id="Qwen/Qwen2.5-Omni-7B",                output_dir=output_dir,                files="all",                patterns=["*.safetensors*", "*.json", "*.txt"],                max_retries=max_retries,            )        else:            logger.error(f"No download function for model: {model_name}")            return False        if result:            print(f"\n{'='*60}")            print(f"Successfully downloaded: {model_name}")            print(f"{'='*60}\n")        else:            print(f"\n{'='*60}")            print(f"Failed to download: {model_name}")            print(f"{'='*60}\n")        return result    except Exception as e:        logger.error(f"Error downloading model '{model_name}': {e}")        print(f"\n{'='*60}")        print(f"Error downloading {model_name}: {e}")        print(f"{'='*60}\n")        return Falsedef delete_model(model_name: str, project_root: Path | None = None) -> bool:    """Delete a model directory."""    if project_root is None:        project_root = PROJECT_ROOT    if model_name not in MODEL_CONFIGS:        logger.error(f"Unknown model: {model_name}")        return False    config = MODEL_CONFIGS[model_name]    model_path = project_root / config["output_dir"]    if not model_path.exists():        logger.info(f"Model path does not exist: {model_path}")        return True    try:        shutil.rmtree(model_path)        logger.info(f"Deleted model directory: {model_path}")        return True    except Exception as e:        logger.error(f"Failed to delete model directory {model_path}: {e}")        return Falsedef list_models(project_root: Path | None = None):    """List all models and their download status."""    if project_root is None:        project_root = PROJECT_ROOT    print("\n" + "=" * 60)    print("Cozy TTS Model Status")    print("=" * 60)    for model_name, config in MODEL_CONFIGS.items():        is_downloaded = is_model_downloaded(model_name, project_root)        status = "✓ Downloaded" if is_downloaded else "→ Not downloaded"        print(f"\n{status}: {model_name}")        print(f"  Description: {config['description']}")        print(f"  Output: {config['output_dir']}")    print("\n" + "=" * 60 + "\n")# =============================================================================# CLI# =============================================================================def main():    parser = argparse.ArgumentParser(        description="Download TTS models for Cozy TTS using aria2c",        formatter_class=argparse.RawDescriptionHelpFormatter,        epilog="""Examples:  # List all models  python download_models.py --list  # Download all models  python download_models.py --all  # Download specific model  python download_models.py --kokoro  # Delete and re-download a model  python download_models.py --delete kokoro --kokoro  # Clean up incomplete downloads  python download_models.py --cleanup-incomplete  # Validate all downloaded models  python download_models.py --validate-all        """    )    # List    parser.add_argument("--list", action="store_true", help="List all models and their status")    # Validation and cleanup    parser.add_argument("--cleanup-incomplete", action="store_true", help="Clean up incomplete/partial downloads")    parser.add_argument("--cleanup-dry-run", action="store_true", help="Show what would be deleted without actually deleting (use with --cleanup-incomplete)")    parser.add_argument("--validate", type=str, metavar="MODEL", help="Validate files for a specific model")    parser.add_argument("--validate-all", action="store_true", help="Validate all downloaded models")    # Individual models    parser.add_argument("--kokoro", action="store_true", help="Download Kokoro model")    parser.add_argument("--vibevoice", action="store_true", help="Download VibeVoice 1.5B model")    parser.add_argument("--vibevoice-7b", dest="vibevoice_7b", action="store_true", help="Download VibeVoice 7B model")    parser.add_argument("--maya1", action="store_true", help="Download Maya1 model")    parser.add_argument("--gptsovits", action="store_true", help="Download GPT-SoVITS model")    parser.add_argument("--gptsovits-pretrained", dest="gptsovits_pretrained", action="store_true", help="Download GPT-SoVITS pretrained BERT model (optional, auto-downloaded if missing)")    parser.add_argument("--gptsovits-cnhubert", dest="gptsovits_cnhubert", action="store_true", help="Download GPT-SoVITS pretrained CNHubert model (optional, auto-downloaded if missing)")    parser.add_argument("--indextts", action="store_true", help="Download IndexTTS model")    parser.add_argument("--qwen-omni", dest="qwen_omni", action="store_true", help="Download Qwen-Omni model for Audio QA (25GB, requires GPU) - safetensors format")    parser.add_argument("--qwen-omni-gguf", dest="qwen_omni_gguf", action="store_true", help="Download Qwen-Omni GGUF model for Audio QA with llama.cpp (~6GB, recommended)")    parser.add_argument("--qwen2.5-omni-7b", dest="qwen2_5_omni_7b", action="store_true", help="Download Qwen2.5-Omni-7B for Audio QA (~14GB) - smaller & faster loading")    # All models    parser.add_argument("--all", action="store_true", help="Download all models")    # Delete    parser.add_argument("--delete", type=str, help="Delete a specific model before downloading")    # Retries    parser.add_argument("--max-retries", type=int, default=10, help="Maximum download retry attempts (default: 10)")    args = parser.parse_args()    # Detect project root using smart detection (same as find_incomplete_downloads)    file_path = Path(__file__).resolve()    current = file_path    while current != current.parent:        if (current / "pyproject.toml").exists() or (current / "backend" / "pyproject.toml").exists():            break        current = current.parent    # Determine the actual project root    # Prefer project root level over backend directory    if (current.parent / "models").exists() and current.name == "backend":        # We're in backend/ and models/ is one level up (most common case)        project_root = current.parent    elif current.name == "backend":        # We're in backend/ but parent doesn't have models        project_root = current    elif (current / "models").exists():        # models/ exists at this level        project_root = current    elif (current / "backend" / "models").exists():        # backend/models/ exists        project_root = current    else:        # Fallback to the original calculation        project_root = PROJECT_ROOT    # Handle list    if args.list:        list_models(project_root)        return 0    # Handle delete    if args.delete:        model_to_delete = args.delete.lower()        if model_to_delete in MODEL_CONFIGS:            delete_model(model_to_delete, project_root)        else:            print(f"Unknown model: {args.delete}")            return 1    # Handle cleanup incomplete downloads    if args.cleanup_incomplete:        dry_run = args.cleanup_dry_run        print("\n" + "=" * 60)        print("Incomplete Download Cleanup")        print("=" * 60)        if dry_run:            print("DRY RUN MODE - No files will be deleted\n")        result = cleanup_incomplete_downloads(project_root / "models", dry_run=dry_run)        if dry_run:            files_to_delete = result.get("would_delete", [])        else:            files_to_delete = result.get("deleted", [])        space_freed = result.get("space_freed", 0)        if files_to_delete:            print(f"\nFound {len(files_to_delete)} incomplete download(s):")            for f in files_to_delete:                size = f.stat().st_size if f.exists() else 0                print(f"  - {f.relative_to(project_root)} ({size:,} bytes)")            print(f"\nTotal space that would be freed: {space_freed:,} bytes (~{space_freed / (1024**3):.2f} GB)")            if not dry_run:                print(f"Total space freed: {space_freed:,} bytes (~{space_freed / (1024**3):.2f} GB)")                print("\nCleanup completed successfully!")        else:            print("No incomplete downloads found.")        print("=" * 60 + "\n")        # If only doing cleanup, exit here        if not any([args.all, args.kokoro, args.vibevoice, args.vibevoice_7b,                    args.maya1, args.gptsovits, args.gptsovits_pretrained,                    args.gptsovits_cnhubert, args.indextts, args.qwen_omni,                    args.qwen_omni_gguf, args.qwen2_5_omni_7b]):            return 0    # Handle validate    if args.validate:        model_name = args.validate.lower()        if model_name not in MODEL_CONFIGS:            print(f"Unknown model: {args.validate}")            return 1        print(f"\nValidating model: {model_name}")        result = validate_model_files(model_name, project_root)        valid = result.get("valid", [])        invalid = result.get("invalid", [])        if valid:            print(f"\n✓ Valid files: {len(valid)}")            for f in valid:                print(f"  - {f.relative_to(project_root)} ({f.stat().st_size:,} bytes)")        if invalid:            print(f"\n✗ Invalid files: {len(invalid)}")            for f in invalid:                is_valid, msg = validate_downloaded_file(f)                print(f"  - {f.relative_to(project_root)}: {msg}")        if not valid and not invalid:            print(f"\nModel '{model_name}' is not downloaded.")        return 0 if not invalid else 1    # Handle validate all    if args.validate_all:        print("\n" + "=" * 60)        print("Model Validation Report")        print("=" * 60)        all_valid = True        for model_name in MODEL_CONFIGS.keys():            if is_model_downloaded(model_name, project_root):                result = validate_model_files(model_name, project_root)                invalid = result.get("invalid", [])                valid = result.get("valid", [])                if invalid:                    all_valid = False                    print(f"\n✗ {model_name}: {len(invalid)} invalid file(s)")                    for f in invalid:                        is_valid, msg = validate_downloaded_file(f)                        print(f"    - {f.name}: {msg}")                else:                    print(f"\n✓ {model_name}: All {len(valid)} files valid")        print("\n" + "=" * 60)        if all_valid:            print("All downloaded models are valid!")        else:            print("Some models have invalid files. Run with --validate <model> for details.")        print("=" * 60 + "\n")        # If only doing validation, exit here        if not any([args.all, args.kokoro, args.vibevoice, args.vibevoice_7b,                    args.maya1, args.gptsovits, args.gptsovits_pretrained,                    args.gptsovits_cnhubert, args.indextts, args.qwen_omni,                    args.qwen_omni_gguf, args.qwen2_5_omni_7b]):            return 0 if all_valid else 1    # Determine which models to download    models_to_download = []    if args.all:        models_to_download = list(MODEL_CONFIGS.keys())    else:        if args.kokoro:            models_to_download.append("kokoro")        if args.vibevoice:            models_to_download.append("vibevoice")        if args.vibevoice_7b:            models_to_download.append("vibevoice-7b")        if args.maya1:            models_to_download.append("maya1")        if args.gptsovits:            models_to_download.append("gptsovits")        if args.gptsovits_pretrained:            models_to_download.append("gptsovits-pretrained")        if args.gptsovits_cnhubert:            models_to_download.append("gptsovits-cnhubert")        if args.indextts:            models_to_download.append("indextts")        if args.qwen_omni:            models_to_download.append("qwen-omni")        if args.qwen_omni_gguf:            models_to_download.append("qwen-omni-gguf")        if args.qwen2_5_omni_7b:            models_to_download.append("qwen2.5-omni-7b")    if not models_to_download:        parser.print_help()        return 1    # Download models    print(f"\nUsing aria2c for reliable downloads with {args.max_retries} retries...\n")    success_count = 0    failed_models = []    for model_name in models_to_download:        if download_model_by_name(model_name, project_root, args.max_retries):            success_count += 1        else:            failed_models.append(model_name)    # Print summary    print("\n" + "=" * 60)    print("Download Summary")    print("=" * 60)    print(f"Successfully downloaded: {success_count}/{len(models_to_download)}")    if failed_models:        print(f"Failed models: {', '.join(failed_models)}")        return 1    print("All models downloaded successfully!")    print("=" * 60 + "\n")    return 0# =============================================================================# Backward Compatibility Functions for API# These maintain the old function signatures used by models.py API# =============================================================================def _get_output_dir() -> Path:    """Get the models output directory."""    return ROOT_MODELS_DIRdef download_kokoro(progress_callback: Callable[[float], None] | None = None) -> bool:    """Download Kokoro model - API compatible wrapper."""    return _download_kokoro_internal(_get_output_dir() / "kokoro")def download_vibevoice_1_5b(progress_callback: Callable[[float], None] | None = None) -> bool:    """Download VibeVoice 1.5B model - API compatible wrapper."""    return _download_vibevoice_1_5b_internal(_get_output_dir() / "vibevoice-1.5b")def download_vibevoice_7b(progress_callback: Callable[[float], None] | None = None) -> bool:    """Download VibeVoice 7B model - API compatible wrapper."""    return _download_vibevoice_7b_internal(_get_output_dir() / "vibevoice-7b")def download_indextts(progress_callback: Callable[[float], None] | None = None) -> bool:    """Download IndexTTS model - API compatible wrapper."""    return _download_indextts_internal(_get_output_dir() / "indextts")def download_gpt_sovits(progress_callback: Callable[[float], None] | None = None) -> bool:    """Download GPT-SoVITS model - API compatible wrapper."""    return _download_gptsovits_internal(_get_output_dir() / "gpt_sovits")def download_maya1(progress_callback: Callable[[float], None] | None = None) -> bool:    """Download Maya1 model - API compatible wrapper."""    return _download_maya1_internal(_get_output_dir() / "maya1")def download_qwen_omni(progress_callback: Callable[[float], None] | None = None) -> bool:    """Download Qwen-Omni model - API compatible wrapper."""    return _download_qwen_omni_internal(_get_output_dir() / "qwen-omni")def delete_model_directory(model_name: str) -> bool:    """Delete a model directory - API compatible wrapper."""    return delete_model(model_name)def validate_and_redownload_if_needed(    model_name: str,    progress_callback: Callable[[float], None] | None = None,) -> bool:    """Validate and re-download if needed - API compatible wrapper."""    # Check if model exists, download if not    if not is_model_downloaded(model_name):        return download_model_by_name(model_name)    return Trueif __name__ == "__main__":    sys.exit(main())